contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (1) + (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        address sender = address(this);

        // Establish a pre-existing positive balance for address(this).
        c.addToBalance{value: 1}(); if (__ESBMC_reverted()) return;

        uint before = c.getBalance(sender); if (__ESBMC_reverted()) return;
        require(before > 0);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint after_ = c.getBalance(sender); if (__ESBMC_reverted()) return;
        assert(after_ > before);
    }

    receive() external payable {}
}

