pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        address sender = address(this);
        try c.addToBalance{value: 1}() {} catch { return; }
        uint256 before;
        try c.getBalance(sender) returns (uint256 __r) { before = __r; } catch { return; }
        vm.assume(before > 0);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 after_;
        try c.getBalance(sender) returns (uint256 __r) { after_ = __r; } catch { return; }
        assertTrue(after_ > before);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
